-- Migration 0010_usage: generated by drizzle-kit, hand-reviewed before commit.
-- Reviewed-by: Claude (agent, #218)
-- Usage metering tables (#218, #30 part 1), next to usage_counter (0005_billing): usage_reservation,
-- usage_event (the ledger, idempotent per workspace), budget_override (staff overrides, reason and
-- expiry required) and usage_period_summary (month-end totals). All four are tenant tables built with
-- tenantTable(): NOT NULL workspace_id referencing organization ON DELETE cascade, a workspace-led
-- index, and ENABLE + FORCE RLS with ws_isolation at the end (exactly tenantPolicy()).
-- No customer content: key and purpose are dotted lowercase identifiers, and usage_event.metadata
-- must pass usage_metadata_ids_only() (an object of `*_id` keys with short id-string values).
-- Hand edits: usage_metadata_ids_only() and its grants come first because a CHECK calls it; the RLS
-- statements are appended. New objects only: nothing existing is altered or dropped.
CREATE FUNCTION usage_metadata_ids_only(metadata jsonb) RETURNS boolean
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
  AS $$
    SELECT jsonb_typeof(metadata) = 'object' AND NOT EXISTS (
      SELECT 1 FROM jsonb_each(metadata) AS e(k, v)
      WHERE k !~ '^[a-z][a-z0-9_]*_id$'
        OR jsonb_typeof(v) <> 'string'
        OR (v #>> '{}') !~ '^[A-Za-z0-9_:-]{1,128}$'
    )
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION usage_metadata_ids_only(jsonb) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION usage_metadata_ids_only(jsonb) TO causedeck_app;--> statement-breakpoint
CREATE TABLE "budget_override" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" text NOT NULL,
	"limit_value" bigint NOT NULL,
	"set_by" uuid NOT NULL,
	"reason" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "budget_override_limit_chk" CHECK (limit_value >= 0),
	CONSTRAINT "budget_override_reason_chk" CHECK (length(btrim(reason)) > 0),
	CONSTRAINT "budget_override_key_chk" CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*$' and length(key) <= 64)
);
--> statement-breakpoint
CREATE TABLE "usage_event" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" text NOT NULL,
	"amount" bigint NOT NULL,
	"idempotency_key" text NOT NULL,
	"metadata" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "usage_event_key_chk" CHECK (key ~ '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*$' and length(key) <= 64),
	CONSTRAINT "usage_event_metadata_chk" CHECK (usage_metadata_ids_only(metadata))
);
--> statement-breakpoint
